#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, m;
    cin >> n >> m;

    int w = min(n, m);
    int L = max(n, m);
    int fullMask = (1 << w) - 1;
    int size = 1 << w;

    const int INF = INT_MAX / 2;

    vector<vector<int>> dp(size, vector<int>(size, INF));

    // initialize for the first column (c = 0)
    for (int s = 0; s < size; s++) {
        int vert = ((s << 1) | (s >> 1)) & fullMask;
        int pd = (s | vert) & fullMask;
        int cnt = __builtin_popcount(s);
        if (cnt < dp[s][pd]) dp[s][pd] = cnt;
    }

    for (int c = 1; c < L; c++) {
        vector<vector<int>> ndp(size, vector<int>(size, INF));
        for (int prevS = 0; prevS < size; prevS++) {
            for (int prevPD = 0; prevPD < size; prevPD++) {
                int v = dp[prevS][prevPD];
                if (v >= INF) continue;
                for (int curS = 0; curS < size; curS++) {
                    int fullDomPrev = prevPD | curS;
                    if (fullDomPrev != fullMask) continue;
                    int vertCur = ((curS << 1) | (curS >> 1)) & fullMask;
                    int pdCur = (curS | vertCur | prevS) & fullMask;
                    int nv = v + __builtin_popcount(curS);
                    if (nv < ndp[curS][pdCur]) ndp[curS][pdCur] = nv;
                }
            }
        }
        dp = ndp;
    }

    int best = INF;
    for (int s = 0; s < size; s++) {
        if (dp[s][fullMask] < best) best = dp[s][fullMask];
    }

    cout << (n * m - best) << endl;

    return 0;
}
